import json, decimal
from pathlib import Path
analysis_path = Path('/root/oncocooler_analysis.json')
summary_path = Path('/root/oncocooler_summary.md')
data = json.loads(analysis_path.read_text())
expected_top = {'assumptions', 'programs', 'totals', 'recommendation'}
expected_assumptions = {
    'dispatches_per_year_10_day', 'dispatches_per_year_20_day',
    'days_per_dispatch_10_day', 'days_per_dispatch_20_day',
    'switch_threshold_usd', 'site_override_rule'
}
assert set(data) == expected_top, set(data)
assert set(data['assumptions']) == expected_assumptions, set(data['assumptions'])
codes = [p['program_code'] for p in data['programs']]
assert codes == sorted(codes), codes
assert data['assumptions']['days_per_dispatch_20_day'] == 20
assert data['assumptions']['dispatches_per_year_20_day'] == 18

def check_money(v, path):
    if isinstance(v, float):
        d = decimal.Decimal(str(v))
        assert abs(d.as_tuple().exponent) <= 2, (path, v)

for p in data['programs']:
    for k, v in p.items():
        if isinstance(v, (int, float)) and ('usd' in k or k.endswith('cost')):
            check_money(v, f"programs.{p['program_code']}.{k}")
        if isinstance(v, dict):
            for kk, vv in v.items():
                if isinstance(vv, (int, float)) and 'usd' in kk:
                    check_money(vv, f"programs.{p['program_code']}.{k}.{kk}")
for k, v in data['totals'].items():
    check_money(v, f'totals.{k}')
nonempty = [line for line in summary_path.read_text().splitlines() if line.strip()]
assert 4 <= len(nonempty) <= 8, len(nonempty)
for needle in ['Total 10-day margin (USD)', 'Total 20-day margin (USD)', 'Absolute difference (USD)', data['recommendation']]:
    assert needle in summary_path.read_text(), needle
print('targeted validation passed')
